// lookup demo — Sun (jahdb demo program)
var DATA={"Sun":"The Sun holds 99.86 percent of all mass in the solar system, fusing 600 million tons of hydrogen every second. Its light takes 8 minutes 20 seconds to reach Earth, and its planets, dwarf planets, moons, and comets are all bound by its gravity."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("G-type main-sequence star"));

